import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isScanning, setIsScanning] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const scanTimer = setTimeout(() => setIsScanning(false), 1200);
    const exitTimer = setTimeout(() => setIsExiting(true), 3200);
    const finish = setTimeout(onComplete, 4000);

    return () => { 
      clearTimeout(scanTimer);
      clearTimeout(exitTimer);
      clearTimeout(finish);
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#FFF24D] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE SCANLINE: Lenin Blue laser "printing" the app */}
      {isScanning && (
        <motion.div 
          initial={{ left: "-10%" }}
          animate={{ left: "110%" }}
          transition={{ duration: 1.2, ease: "linear" }}
          className="absolute top-0 bottom-0 w-2 bg-[#003366] z-50 shadow-[0_0_40px_#003366]"
        />
      )}

      {/* 2. THE CORE UNIT */}
      <motion.div 
        animate={isExiting ? { scale: 0, rotate: -10, opacity: 0 } : { scale: 1 }}
        transition={{ duration: 0.8, ease: [0.76, 0, 0.24, 1] }}
        className="flex flex-col items-center"
      >
        <div className="relative flex items-center animate-slice">
          {/* BEET RED LOGO WITH CHROMATIC VIBRATION */}
          <h1 className={`text-[12rem] md:text-[20rem] font-[1000] italic text-[#AB1717] tracking-tighter leading-none select-none ${!isScanning ? 'animate-beet-pulse' : ''}`}>
            T2T
          </h1>
        </div>

        {/* THE GRASSY GREEN WORKER TAG: Appearing like a digital error/glitch */}
        <motion.div 
          initial={{ opacity: 0, skewX: 45 }}
          animate={{ opacity: 1, skewX: -12 }}
          transition={{ delay: 1.3, duration: 0.4 }}
          className="mt-[-40px] md:mt-[-60px] bg-[#47510B] px-14 py-4"
        >
          <span className="text-[#FFF24D] font-black text-3xl md:text-5xl uppercase italic tracking-[0.5em]">
            Worker
          </span>
        </motion.div>
      </motion.div>

      {/* 3. LENIN BLUE "VOID" - The Background Texture */}
      <div className="absolute inset-0 opacity-10 pointer-events-none">
        <div className="w-full h-full bg-[radial-gradient(#003366_1.5px,transparent_1.5px)] [background-size:32px_32px]" />
      </div>

      {/* 4. TACTICAL OVERLAY */}
      <div className="absolute top-10 right-10 flex items-center gap-4 text-[#003366] font-black italic text-xs tracking-widest">
        <span>ESTABLISHING_LINK</span>
        <div className="w-3 h-3 bg-[#AB1717] animate-ping" />
      </div>
    </div>
  );
};

export default WorkerSplash;
